/* Imprimante 3D en photo (option model : neptune4pro = Elegoo Neptune 4 Pro, kobrax = Anycubic Kobra X) :
   photo détourée + calques animés (buse qui chauffe / imprime, chaleur du plateau, objet qui monte avec la progression,
   tête lumineuse qui balaie l'objet, écran éteint / en erreur). Sans model : le dessin d'origine. */
const P3D_PHOTO = {
  neptune4pro: { img: "data:image/webp;base64,", x: 6.1, w: 107.8, tip: [57.3, 72], bed: [56.8, 109.7], scr: "91.4,106.7 101.1,106 108.7,117.1 98,118.7", hw: 34 },
  kobrax: { img: "data:image/webp;base64,", x: 10.6, w: 98.8, tip: [55.1, 90.8], bed: [52.1, 116.6], scr: "67.2,116.1 83.8,116.6 79.9,124.5 63.1,124.3", hw: 30 },
};
const P3D_DRAW = SVG.printer_3d;
SVG.printer_3d = (c) => {
  const k = String((c && c.model) || "").toLowerCase().replace(/[^a-z0-9]/g, ""), g = P3D_PHOTO[k];
  if (!g) return P3D_DRAW(c);
  const [tx, ty] = g.tip, [bx, by] = g.bed, OH = 14; // objet imprimé : 14 unités de haut au maximum
  const waves = [-0.36, -0.12, 0.12, 0.36].map((d) => `<path d="M${(bx + d * g.hw).toFixed(1)} ${by - 2}q-2-3 0-6t0-6"/>`).join("");
  return `<defs>${DEFS}
<linearGradient id="ID-fil" x1="0" x2="1"><stop offset="0" style="stop-color:var(--fil)" stop-opacity=".75"/><stop offset=".45" style="stop-color:var(--fil)"/><stop offset="1" style="stop-color:var(--fil)" stop-opacity=".7"/></linearGradient>
<pattern id="ID-layers" width="4" height="1.3" patternUnits="userSpaceOnUse"><rect width="4" height=".55" fill="#000" opacity=".18"/></pattern>
<clipPath id="ID-obj"><rect class="objclip" data-b="${by}" data-h="${OH}" x="${bx - 9}" y="${by}" width="18" height="0"/></clipPath>
<linearGradient id="ID-glass" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3a4049"/><stop offset="1" stop-color="#0e1013"/></linearGradient>
<radialGradient id="ID-glow"><stop offset="0" style="stop-color:var(--p3-tip)"/><stop offset=".4" style="stop-color:var(--p3-tip)" stop-opacity=".6"/><stop offset="1" style="stop-color:var(--p3-tip)" stop-opacity="0"/></radialGradient>
</defs>
<g class="p3 p3-${k}">
<ellipse cx="60" cy="136" rx="46" ry="3.5" fill="url(#ID-shadow)"/>
<g class="p3-photo"><image href="${g.img}" x="${g.x}" y="2" width="${g.w}" height="136" preserveAspectRatio="none"/></g>
<g class="bedheat">${waves}</g>
<g clip-path="url(#ID-obj)"><g class="object">
  <path d="M${bx - 6} ${by}v-${OH - 3}q0-3 3-3h6q3 0 3 3v${OH - 3}z" fill="url(#ID-fil)"/>
  <path d="M${bx - 6} ${by}v-${OH - 3}q0-3 3-3h6q3 0 3 3v${OH - 3}z" fill="url(#ID-layers)"/>
</g></g>
<circle class="p3-spark" cx="${bx}" cy="${by}" r="1.3"/>
<circle class="p3-tip" cx="${tx}" cy="${ty}" r="4" fill="url(#ID-glow)"/>
<polygon class="p3-scr" points="${g.scr}" fill="url(#ID-glass)"/>
</g>`;
};
